#nullable enable
using System.Collections.Immutable;
using System.Globalization;
using Marten.Events.Projections;
using HourBooking.Contracts;

namespace HourBooking.Views;

/// <summary>
/// Context: booking. Slice: fill-zero-hours. One row per (employee, project) — declared as
/// identity="employeeId, projectId" on the read model.
///
/// THE TODO LIST the ZeroFillProcessor works, and the reason the automation pattern insists on a view
/// at all: <c>EmployeeRemovedFromProject</c> puts a row on the list, the processor works the row, and
/// the resulting <c>ZeroHoursFilled</c> ticks the day off. Skip the view and you lose both the record
/// of pending work and the thing that stops the processor working the same row twice.
///
/// The two feeding edges mean OPPOSITE things, and the checker cannot see the difference — blind spot
/// 5 in OPEN-QUESTIONS.md, which is how this view once came to be "sourced from its own output":
///
///   EmployeeRemovedFromProject -> CREATE the row. This is the only event that puts work on the list.
///   ZeroHoursFilled            -> TICK ONE DAY OFF. Completion, never supply.
/// </summary>
public sealed record ZeroFillTodo
{
    public string Id { get; init; } = default!;

    public Guid EmployeeId { get; init; }
    public Guid ProjectId { get; init; }

    /// <summary>The day the removal takes effect. The fill runs from here to the end of ITS month.</summary>
    public DateOnly EffectiveFrom { get; init; }

    /// <summary>
    /// True from the moment a removal puts this row on the list, and never cleared. It is what tells
    /// the processor that a row is real work: a <c>ZeroHoursFilled</c> for an (employee, project) with
    /// no removal on record would otherwise materialise a row out of a TICK-OFF, and the processor
    /// would then treat the automation's own output as a fresh instruction.
    ///
    /// It cannot be cleared on completion, because "every working day to month end is filled" is a
    /// question only the processor can answer — it needs WorkingDays, and a projection cannot query.
    /// </summary>
    public bool Pending { get; init; }

    /// <summary>
    /// The tick-off itself: the days this row has already produced a ZeroHoursFilled for. The decider
    /// checks the stream as well, so this is the cheap first line of defence rather than the only one.
    /// </summary>
    public ImmutableHashSet<DateOnly> FilledDates { get; init; } = ImmutableHashSet<DateOnly>.Empty;

    /// <summary>
    /// Derived from EffectiveFrom, not carried: "the rest of THAT month" is the month the removal fell
    /// in, so the Timesheet stream key this row feeds is fixed the moment the row is created.
    /// </summary>
    public string Month => EffectiveFrom.ToString("yyyy-MM", CultureInfo.InvariantCulture);

    public static string RowId(Guid employeeId, Guid projectId) => $"{employeeId}:{projectId}";

    public bool IsFilled(DateOnly date) => FilledDates.Contains(date);
}

public sealed class ZeroFillTodoProjection : MultiStreamProjection<ZeroFillTodo, string>
{
    public ZeroFillTodoProjection()
    {
        // Both events carry employeeId + projectId, which is the only reason this view is projectable
        // at the grain the model declares.
        Identity<EmployeeRemovedFromProject>(e => ZeroFillTodo.RowId(e.EmployeeId, e.ProjectId));
        Identity<ZeroHoursFilled>(e => ZeroFillTodo.RowId(e.EmployeeId, e.ProjectId));
    }

    /// <summary>Puts the row on the list. The only event here that means "there is work to do".</summary>
    public static ZeroFillTodo Apply(EmployeeRemovedFromProject e, ZeroFillTodo current) => current with
    {
        EmployeeId = e.EmployeeId,
        ProjectId = e.ProjectId,
        EffectiveFrom = e.EffectiveFrom,
        Pending = true,
    };

    /// <summary>
    /// Ticks one day off. It deliberately does NOT set EffectiveFrom or Pending: this event is the
    /// automation's own output, and letting it create work would be exactly the loop the todo list
    /// exists to prevent.
    /// </summary>
    public static ZeroFillTodo Apply(ZeroHoursFilled e, ZeroFillTodo current) => current with
    {
        EmployeeId = e.EmployeeId,
        ProjectId = e.ProjectId,
        FilledDates = current.FilledDates.Add(e.Date),
    };
}
